+    updateCriticalBatteryHold();

     auto watcher = new QDBusPendingCallWatcher(m_powerProfilesPropertiesInterface->GetAll(m_powerProfilesInterface->interface()));
     connect(watcher, &QDBusPendingCallWatcher::finished, this, [this, watcher] {
@@ -85,9 +93,64 @@ PowerProfile::~PowerProfile() = default;

 void PowerProfile::onProfileLoad(const QString & /*previousProfile*/, const QString & /*newProfile*/)
 {
-    if (!m_configuredProfile.isEmpty()) {
-        setProfile(m_configuredProfile);
+    if (m_configuredProfile.isEmpty()) {
+        return;
     }
+    ++m_pendingProfileSets;
+    auto watcher = new QDBusPendingCallWatcher(
+        m_powerProfilesPropertiesInterface->Set(m_powerProfilesInterface->interface(), activeProfileProperty, QDBusVariant(m_configuredProfile)));
+    connect(watcher, &QDBusPendingCallWatcher::finished, this, [this, watcher] {
+        watcher->deleteLater();
+        // Setting the profile releases all holds, so the critical battery one is applied only now
+        if (--m_pendingProfileSets == 0) {
+            applyCriticalBatteryHold();
+        }
+    });
+}
+
+void PowerProfile::updateCriticalBatteryHold()
+{
+    const bool hold = core()->isBatteryCritical() && core()->globalSettings()->batteryCriticalPowerSaver();
+    if (hold == m_criticalBatteryHold) {
+        return;
+    }
+    m_criticalBatteryHold = hold;
+    if (m_pendingProfileSets == 0) {
+        applyCriticalBatteryHold();
+    }
+}
+
+void PowerProfile::applyCriticalBatteryHold()
+{
+    if (m_criticalBatteryHold) {
+        holdPowerSaverForCriticalBattery();
+    } else if (m_criticalBatteryHoldCookie) {
+        m_powerProfilesInterface->ReleaseProfile(m_criticalBatteryHoldCookie);
+        m_criticalBatteryHoldCookie = 0;
+    }
+}
+
+void PowerProfile::holdPowerSaverForCriticalBattery()
+{
+    auto watcher = new QDBusPendingCallWatcher(
+        m_powerProfilesInterface->HoldProfile(QStringLiteral("power-saver"), i18n("Battery level is critical"), QStringLiteral("powerdevil")));
+    connect(watcher, &QDBusPendingCallWatcher::finished, this, [this, watcher] {
+        watcher->deleteLater();
+        QDBusPendingReply<unsigned int> reply = *watcher;
+        if (reply.isError()) {
+            qCWarning(POWERDEVIL) << "Failed to hold the power-saver profile at critical battery level:" << reply.error().message();
+            return;
+        }
+        if (!m_criticalBatteryHold) {
+            // The battery stopped being critical while waiting for the reply
+            m_powerProfilesInterface->ReleaseProfile(reply.value());
+            return;
+        }
+        if (m_criticalBatteryHoldCookie) {
+            m_powerProfilesInterface->ReleaseProfile(m_criticalBatteryHoldCookie);
+        }
+        m_criticalBatteryHoldCookie = reply.value();
+    });
 }

 bool PowerProfile::loadAction(const PowerDevil::ProfileSettings &profileSettings)
